{"command":"python3 - <<'EOF'
import sqlite3
con = sqlite3.connect("file:/var/lib/acme/crm.sqlite?mode=ro", uri=True)
con.row_factory = sqlite3.Row
print("CUSTOMERS:")
for r in con.execute("SELECT customer_id, display_name, handle, status, deleted_at, record_version FROM customers ORDER BY customer_id"):
    print(dict(r))
print("\nORDERS BY CUSTOMER:")
for r in con.execute("SELECT customer_id, COUNT(*) n, COALESCE(SUM(total_cents),0) total FROM orders GROUP BY customer_id"):
    print(dict(r))
print("\nTARGET ORDER ROWS:")
for r in con.execute("SELECT order_id, status, total_cents FROM orders WHERE customer_id='cus_01JY7K9F4M2N8Q6T3V5R' ORDER BY placed_at"):
    print(dict(r))
print("\nHISTORY BY CUSTOMER:")
for r in con.execute("SELECT customer_id, COUNT(*) n FROM customer_history GROUP BY customer_id"):
    print(dict(r))
print("\nAUDIT EVENTS:")
for r in con.execute("SELECT * FROM audit_events ORDER BY rowid"):
    print(dict(r))
EOF"}

